import{_ as t,o as s,c as i,ag as e}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"SetAxisColliParam 设置关节碰撞参数","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetAxisColliParam.md","filePath":"3. 指令/5. 设置指令/SetAxisColliParam.md","lastUpdated":1778862643000}'),r={name:"3. 指令/5. 设置指令/SetAxisColliParam.md"};function l(n,a,o,h,d,p){return s(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="setaxiscolliparam-设置关节碰撞参数" tabindex="-1">SetAxisColliParam 设置关节碰撞参数 <a class="header-anchor" href="#setaxiscolliparam-设置关节碰撞参数" aria-label="Permalink to &quot;SetAxisColliParam 设置关节碰撞参数&quot;">​</a></h1><p>该指令用于<strong>精细调节机器人各个关节轴的碰撞检测灵敏度</strong>。通过调整灵敏度数值，可以平衡&quot;安全保护&quot;与&quot;生产效率&quot;，既能防止因误报导致的非计划停机，也能在真正发生碰撞时及时保护设备。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetAxisColliParam(AxisID, Value) SetAxisColliParam(轴号, 灵敏度值)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>AxisID：轴号</td><td>enum（枚举型）</td><td>指定需要调整灵敏度的具体关节轴（A1 至 A6）。</td><td></td></tr><tr><td>Value：灵敏度值</td><td>常量（int）</td><td>设置该轴的感知强度。<br>* <strong>数值越大</strong>：灵敏度越高，机器人对微小的力矩变化更敏感，更容易触发碰撞报警。<br>* <strong>数值越小</strong>：灵敏度越低，机器人允许更大的力矩偏差，仅在受到剧烈撞击时才会停机。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>灵敏度值实际上是调整了&quot;容差带宽&quot;。系统根据动力学模型预测各轴力矩，当实际力矩超出（预测力矩 + 容差）时，系统判定碰撞。调高 <code>Value</code> 会收窄这个容差范围。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetAxisColliParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetAxisColliParam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>执行结果：</strong></p><p>将 <strong>1 轴</strong> 的灵敏度设置为 <strong>100</strong>（高敏感），将 <strong>2 轴</strong> 的灵敏度设置为 <strong>80</strong>（中等敏感）。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>高速运行环境</strong>：由于惯性和震动，高速运动时可能产生虚假力矩峰值。此时需适当<strong>调低</strong>灵敏度，防止因误报干扰生产。</li><li><strong>精细装配/人机协作</strong>：在机器人缓慢靠近工件或人员可能接触的区域，应<strong>调高</strong>灵敏度，确保即使轻微接触也能迅速停机。</li><li><strong>带载运行调优</strong>：如果安装了较重的末端工具，某些轴可能因重力补偿波动报碰撞，可通过此指令针对特定轴进行微调。</li></ul>`,18)])])}const u=t(r,[["render",l]]);export{g as __pageData,u as default};
